WITH base AS (SELECT *, UPPER(event_type) AS event_type_upper, CASE WHEN page IN ('/cart', '/search') THEN 'Group A' ELSE 'Other' END AS page_group FROM web_events WHERE page IS NOT NULL AND page IS DISTINCT FROM '/cart'), prev_events AS (SELECT *, LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time, id) AS prev_event_time FROM base), with_gaps AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM prev_events), islands AS (SELECT id, session_id, event_type, event_time, duration_sec, page_group, SUM(session_start_flag) OVER (PARTITION BY session_id ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT event_type, DATE_TRUNC('WEEK', event_time) AS week_start, CASE WHEN duration_sec >= 398 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, BIT_OR(duration_sec) AS duration_sec_bit_or, COUNT(CASE WHEN event_type = 'click' THEN 1 END) AS click_count, COUNT(DISTINCT event_type) AS distinct_event_types, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS span_minutes, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min, SIZE(COLLECT_SET(event_type)) AS num_event_types FROM islands GROUP BY CUBE (event_type, DATE_TRUNC('WEEK', event_time), CASE WHEN duration_sec >= 398 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY num_event_types DESC NULLS LAST;
